async function viewPreProcessorsInteractive(context, config) {
    writeProgress("🔄 Loading preprocessor information...");
    const preprocessors = config.preprocessors || [];
    if (preprocessors.length === 0) {
        console.log("\nℹ️  No preprocessors found in configuration.\n");
    }
    else {
        await displayPreProcessorsCore(context, preprocessors);
        console.log();
    }
    await safePrompt([{ type: 'input', name: 'continue', message: 'Press Enter to continue...' }]);
}
async function viewVersionsInteractive(context, config) {
    const preprocessors = config.preprocessors || [];
    if (preprocessors.length === 0) {
        console.log("\nℹ️  No preprocessors found in configuration.\n");
        await safePrompt([{ type: 'input', name: 'continue', message: 'Press Enter to continue...' }]);
        return;
    }
    const selected = await promptPreProcessorSelection(preprocessors, 'Select a preprocessor to view versions:');
    if (!selected)
        return;
    writeProgress(`🔄 Loading versions for ${selected.name}...`);
    const data = await fetchVersionsCore(context, selected);
    if (!data) {
        await safePrompt([{ type: 'input', name: 'continue', message: 'Press Enter to continue...' }]);
        return;
    }
    if (data.versions.length === 0) {
        console.log(`\nℹ️  No versions found for ${selected.name}.\n`);
        console.log("💡 Push a version first using 'lua push preprocessor'.\n");
    }
    else {
        displayVersionsCore(selected, data.versions, data.activeVersionId);
        console.log();
    }
    await safePrompt([{ type: 'input', name: 'continue', message: 'Press Enter to continue...' }]);
}
